    const IMAGE_GENERATION_TOOL_MODEL = "gpt-image-2";
    const THEME_STORAGE_KEY = "aotu-theme";
    const STYLE_STORAGE_KEY = "aotu-style";
    const DEFAULT_STYLE_ID = "jade";
    const STYLE_PRESETS = Object.freeze([
        { id: "jade", name: "玉阶绿", shortDescription: "默认控制台风格", description: "冷静通透，适合日常运维与管理台。", swatches: ["#10b981", "#14b8a6", "#84cc16"] },
        { id: "ocean", name: "深海蓝", shortDescription: "稳重数据风格", description: "深海蓝与海雾青组合，更偏向数据中心气质。", swatches: ["#0f766e", "#0284c7", "#38bdf8"] },
        { id: "amber", name: "琥珀砂", shortDescription: "暖调运营风格", description: "金棕与蜜柑色强调活力和可见度。", swatches: ["#d97706", "#f59e0b", "#fb7185"] },
        { id: "rose", name: "绯雾粉", shortDescription: "柔和品牌风格", description: "偏柔和的玫瑰与珊瑚色，适合更轻盈的界面。", swatches: ["#e11d48", "#fb7185", "#f97316"] },
        { id: "cobalt", name: "钴光蓝", shortDescription: "高对比科技风格", description: "钴蓝与电青更锐利，适合强调技术感。", swatches: ["#2563eb", "#4f46e5", "#06b6d4"] },
        { id: "plum", name: "暮莓紫", shortDescription: "深邃夜幕风格", description: "莓紫与酒红做低饱和混合，更偏夜间工作流。", swatches: ["#7c3aed", "#a855f7", "#ec4899"] },
        { id: "graphite", name: "石墨灰", shortDescription: "极简中性风格", description: "压低色彩表达，保留清爽的工业感和秩序感。", swatches: ["#334155", "#475569", "#94a3b8"] },
        { id: "forest", name: "松林墨", shortDescription: "沉稳自然风格", description: "深松绿与苔藓黄组合，更有自然质感。", swatches: ["#166534", "#15803d", "#a3a948"] },
        { id: "sunset", name: "落日橙", shortDescription: "鲜明增长风格", description: "日落橙与暖红渐变，更强调增长和行动感。", swatches: ["#ea580c", "#f97316", "#ef4444"] },
        { id: "mist", name: "雾屿青", shortDescription: "轻雾冷调风格", description: "灰青与冰蓝更柔和，适合长时间阅读与筛选。", swatches: ["#0f766e", "#14b8a6", "#64748b"] },
    ]);
    const STYLE_PRESET_MAP = new Map(STYLE_PRESETS.map((preset) => [preset.id, preset]));
    const REFERENCE_CACHE_DEFAULT_TTL_MS = 15000;
    const API_TIMEOUT_MS = 45000;
    const referenceCacheStore = new Map();
    let currentPageAbortController = new AbortController();
    let shellNavigationAbortController = null;

    const api = {
        get: async (url, options = {}) => parseResponse(await fetchWithTimeout(url, { cache: "no-store", headers: { "Cache-Control": "no-cache" }, ...options })),
        post: async (url, data) => {
            const result = await parseResponse(await fetchWithTimeout(url, withJson("POST", data)));
            invalidateReferenceCacheByMutation("POST", url);
            return result;
        },
        put: async (url, data) => {
            const result = await parseResponse(await fetchWithTimeout(url, withJson("PUT", data)));
            invalidateReferenceCacheByMutation("PUT", url);
            return result;
        },
        delete: async (url) => {
            const result = await parseResponse(await fetchWithTimeout(url, { method: "DELETE" }));
            invalidateReferenceCacheByMutation("DELETE", url);
            return result;
        },
    };

    function composeAbortSignal(signal, timeoutMs = API_TIMEOUT_MS) {
        const controller = new AbortController();
        const signals = [currentPageAbortController.signal];
        if (signal) signals.push(signal);
        const abort = () => controller.abort();
        signals.forEach((item) => {
            if (item.aborted) {
                controller.abort();
                return;
            }
            item.addEventListener("abort", abort, { once: true });
        });
        const timer = window.setTimeout(() => controller.abort(), Math.max(1, timeoutMs));
        controller.signal.addEventListener("abort", () => {
            window.clearTimeout(timer);
            signals.forEach((item) => item.removeEventListener("abort", abort));
        }, { once: true });
        return controller.signal;
    }

    function normalizeFetchError(error) {
        if (error?.name === "AbortError") {
            return new Error("请求超时或页面已切换，请稍后重试");
        }
        return error;
    }

    async function fetchWithTimeout(url, options = {}) {
        try {
            return await fetch(url, {
                ...options,
                signal: composeAbortSignal(options.signal, options.timeoutMs ?? API_TIMEOUT_MS),
            });
        } catch (error) {
            throw normalizeFetchError(error);
        }
    }

    function getReferenceCacheEntry(url) {
        const entry = referenceCacheStore.get(url);
        if (!entry) return null;
        if (entry.value !== undefined && entry.expiresAt > Date.now()) {
            return entry;
        }
        if (entry.promise) {
            return entry;
        }
        referenceCacheStore.delete(url);
        return null;
    }

    async function getCachedReference(url, options = {}) {
        const ttlMs = Math.max(0, Number(options.ttlMs ?? REFERENCE_CACHE_DEFAULT_TTL_MS));
        const force = options.force === true;
        if (!force) {
            const entry = getReferenceCacheEntry(url);
            if (entry?.value !== undefined) {
                return entry.value;
            }
            if (entry?.promise) {
                return await entry.promise;
            }
        }
        const pending = api.get(url)
            .then((value) => {
                referenceCacheStore.set(url, {
                    value,
                    expiresAt: Date.now() + ttlMs,
                    promise: null,
                });
                return value;
            })
            .catch((error) => {
                referenceCacheStore.delete(url);
                throw error;
            });
        referenceCacheStore.set(url, {
            value: undefined,
            expiresAt: Date.now() + ttlMs,
            promise: pending,
        });
        return await pending;
    }

    function invalidateReferenceCache(matchers = []) {
        if (!Array.isArray(matchers) || !matchers.length) return;
        Array.from(referenceCacheStore.keys()).forEach((key) => {
            if (matchers.some((matcher) => key === matcher || key.startsWith(matcher))) {
                referenceCacheStore.delete(key);
            }
        });
    }

    function invalidateProviderReferenceCache() {
        invalidateReferenceCache([
            "/api/providers/options",
            "/api/providers/playground",
            "/api/providers/summary",
        ]);
    }

    function invalidateModelReferenceCache() {
        invalidateReferenceCache([
            "/api/models/options",
        ]);
    }

    function invalidateReferenceCacheByMutation(method, url) {
        if (!["POST", "PUT", "DELETE"].includes(method)) return;
        if (url.startsWith("/api/providers")) {
            invalidateProviderReferenceCache();
            invalidateModelReferenceCache();
            return;
        }
        if (url.startsWith("/api/models") || url.startsWith("/api/model-mappings")) {
            invalidateModelReferenceCache();
            invalidateProviderReferenceCache();
        }
    }

    async function getProviderOptions(options = {}) {
        return await getCachedReference("/api/providers/options", options);
    }

    async function getProviderPlaygroundOptions(options = {}) {
        return await getCachedReference("/api/providers/playground", options);
    }

    async function getProviderSummary(options = {}) {
        return await getCachedReference("/api/providers/summary", options);
    }

    async function getModelOptions(options = {}) {
        return await getCachedReference("/api/models/options", options);
    }

    function debounce(callback, wait = 300) {
        let timerId = null;
        return (...args) => {
            if (timerId) {
                window.clearTimeout(timerId);
            }
            timerId = window.setTimeout(() => callback(...args), wait);
        };
    }

    function getStoredThemePreference() {
        const storedTheme = window.localStorage.getItem(THEME_STORAGE_KEY);
        return storedTheme === "light" || storedTheme === "dark" ? storedTheme : null;
    }

    function getResolvedTheme() {
        return getStoredThemePreference() || (window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");
    }

    function getStoredStylePresetId() {
        const storedStyle = window.localStorage.getItem(STYLE_STORAGE_KEY);
        return STYLE_PRESET_MAP.has(storedStyle) ? storedStyle : null;
    }

    function getResolvedStylePresetId() {
        return getStoredStylePresetId() || DEFAULT_STYLE_ID;
    }

    function getCurrentTheme() {
        return document.documentElement.dataset.theme === "dark" ? "dark" : "light";
    }

    function getCurrentStylePresetId() {
        const currentStyle = document.documentElement.dataset.style;
        return STYLE_PRESET_MAP.has(currentStyle) ? currentStyle : DEFAULT_STYLE_ID;
    }

    function getStylePreset(styleId = getCurrentStylePresetId()) {
        return STYLE_PRESET_MAP.get(styleId) || STYLE_PRESET_MAP.get(DEFAULT_STYLE_ID);
    }

    function getThemeModeLabel(theme = getCurrentTheme()) {
        return theme === "dark" ? "暗黑模式" : "日间模式";
    }

    function renderAppearancePresetGrid(activeStyleId = getCurrentStylePresetId()) {
        const grid = document.getElementById("appearance-preset-grid");
        if (!grid) return;
        grid.innerHTML = STYLE_PRESETS.map((preset) => {
            const isActive = preset.id === activeStyleId;
            const swatches = preset.swatches
                .map((color) => `<span class="appearance-preset-dot" style="--appearance-preset-color:${color}"></span>`)
                .join("");
            return `
                <button
                    class="appearance-preset-card interactive-btn ${isActive ? "is-active" : ""}"
                    type="button"
                    data-style-preset="${preset.id}"
                    aria-pressed="${isActive ? "true" : "false"}"
                >
                    <span class="appearance-preset-swatch" aria-hidden="true">${swatches}</span>
                    <span class="appearance-preset-copy">
                        <strong>${preset.name}</strong>
                        <small>${preset.description}</small>
                    </span>
                    <span class="appearance-preset-state">${isActive ? "当前风格" : "一键应用"}</span>
                </button>
            `;
        }).join("");
        enhanceInteractiveButtons(grid);
    }

    function syncAppearanceUI() {
        const theme = getCurrentTheme();
        const preset = getStylePreset();
        const themeLabel = document.getElementById("theme-toggle-label");
        const themeButton = document.getElementById("theme-toggle");
        const themeIcon = themeButton?.querySelector("i");
        const styleButton = document.getElementById("style-toggle");
        const styleLabel = document.getElementById("style-toggle-label");
        const styleMeta = document.getElementById("style-toggle-meta");
        const currentMode = document.getElementById("appearance-current-mode");
        const currentStyle = document.getElementById("appearance-current-style");

        if (themeLabel) {
            themeLabel.textContent = theme === "dark" ? "切换日间" : "切换暗黑";
        }
        if (themeButton) {
            themeButton.setAttribute("aria-label", theme === "dark" ? "切换到日间模式" : "切换到暗黑模式");
            themeButton.dataset.theme = theme;
        }
        if (themeIcon) {
            themeIcon.className = theme === "dark" ? "bi bi-sun" : "bi bi-moon-stars";
        }
        if (styleButton) {
            styleButton.setAttribute("aria-label", `打开全站风格选择器，当前风格 ${preset.name}`);
            styleButton.dataset.style = preset.id;
        }
        if (styleLabel) {
            styleLabel.textContent = preset.name;
        }
        if (styleMeta) {
            styleMeta.textContent = preset.shortDescription;
        }
        if (currentMode) {
            currentMode.textContent = getThemeModeLabel(theme);
        }
        if (currentStyle) {
            currentStyle.textContent = preset.name;
        }
        renderAppearancePresetGrid(preset.id);
    }

    function applyTheme(theme) {
        const nextTheme = theme === "dark" ? "dark" : "light";
        document.documentElement.dataset.theme = nextTheme;
        document.documentElement.style.colorScheme = nextTheme;
        syncAppearanceUI();
    }

    function applyStylePreset(styleId) {
        document.documentElement.dataset.style = STYLE_PRESET_MAP.has(styleId) ? styleId : DEFAULT_STYLE_ID;
        syncAppearanceUI();
    }

    let appearanceModalController = null;
    let appearanceModalNode = null;

    function ensureAppearanceModalController() {
        const modal = document.getElementById("appearance-modal");
        const grid = document.getElementById("appearance-preset-grid");
        if (!modal || !grid) return null;
        if (appearanceModalController && appearanceModalNode === modal) {
            return appearanceModalController;
        }
        appearanceModalNode = modal;
        appearanceModalController = modalManager.register({
            modal,
            dialog: modal.querySelector('[role="dialog"]'),
            getInitialFocus: () => modal.querySelector("[data-style-preset][aria-pressed='true']") || document.getElementById("appearance-modal-close"),
        });
        const closeButton = document.getElementById("appearance-modal-close");
        if (closeButton && closeButton.dataset.boundAppearanceClose !== "true") {
            closeButton.dataset.boundAppearanceClose = "true";
            closeButton.addEventListener("click", () => {
                appearanceModalController?.close();
            });
        }
        if (grid.dataset.boundAppearancePresetGrid !== "true") {
            grid.dataset.boundAppearancePresetGrid = "true";
            grid.addEventListener("click", (event) => {
                const button = event.target.closest("[data-style-preset]");
                if (!button) return;
                const preset = getStylePreset(button.dataset.stylePreset);
                window.localStorage.setItem(STYLE_STORAGE_KEY, preset.id);
                applyStylePreset(preset.id);
                showToast(`已切换为${preset.name}`);
            });
        }
        return appearanceModalController;
    }

    function openAppearanceModal(trigger = document.activeElement) {
        const controller = ensureAppearanceModalController();
        if (!controller) return;
        renderAppearancePresetGrid();
        if (controller.isOpen()) return;
        controller.open(trigger);
    }

    function initThemeToggle() {
        applyTheme(getResolvedTheme());
        applyStylePreset(getResolvedStylePresetId());
        const toggle = document.getElementById("theme-toggle");
        if (toggle && toggle.dataset.boundThemeToggle !== "true") {
            toggle.dataset.boundThemeToggle = "true";
            toggle.addEventListener("click", () => {
                const nextTheme = getCurrentTheme() === "dark" ? "light" : "dark";
                window.localStorage.setItem(THEME_STORAGE_KEY, nextTheme);
                applyTheme(nextTheme);
            });
        }
        const styleToggle = document.getElementById("style-toggle");
        if (styleToggle && styleToggle.dataset.boundStyleToggle !== "true") {
            styleToggle.dataset.boundStyleToggle = "true";
            styleToggle.addEventListener("click", () => {
                openAppearanceModal(styleToggle);
            });
        }
        ensureAppearanceModalController();
        const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
        const syncSystemTheme = (event) => {
            if (getStoredThemePreference()) return;
            applyTheme(event.matches ? "dark" : "light");
        };
        if (typeof mediaQuery.addEventListener === "function") {
            mediaQuery.addEventListener("change", syncSystemTheme);
        } else if (typeof mediaQuery.addListener === "function") {
            mediaQuery.addListener(syncSystemTheme);
        }
    }

    function initSiteNavigation() {
        const toggle = document.getElementById("site-nav-toggle");
        const panel = document.getElementById("site-nav-panel");
        if (!toggle || !panel || toggle.dataset.boundSiteNav === "true") return;

        const closeNav = () => {
            panel.classList.remove("is-open");
            toggle.classList.remove("is-open");
            toggle.setAttribute("aria-expanded", "false");
        };

        const openNav = () => {
            panel.classList.add("is-open");
            toggle.classList.add("is-open");
            toggle.setAttribute("aria-expanded", "true");
        };

        toggle.dataset.boundSiteNav = "true";
        toggle.addEventListener("click", () => {
            if (panel.classList.contains("is-open")) {
                closeNav();
                return;
            }
            openNav();
        });

        document.addEventListener("click", (event) => {
            if (!panel.classList.contains("is-open")) return;
            if (panel.contains(event.target) || toggle.contains(event.target)) return;
            closeNav();
        });

        window.addEventListener("resize", () => {
            if (window.innerWidth > 992) closeNav();
        });
    }

    function createModalManager() {
        let activeController = null;

        function getFocusableElements(container) {
            if (!container) return [];
            return Array.from(
                container.querySelectorAll(
                    'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'
                )
            ).filter((element) => !element.hasAttribute("hidden") && element.getAttribute("aria-hidden") !== "true");
        }

        function lockScroll() {
            document.body.classList.add("modal-open");
        }

        function unlockScroll() {
            if (!activeController) {
                document.body.classList.remove("modal-open");
            }
        }

        document.addEventListener("keydown", (event) => {
            if (!activeController) return;

            if (event.key === "Escape") {
                event.preventDefault();
                activeController.close({ reason: "escape" });
                return;
            }

            if (event.key !== "Tab") return;
            const focusable = getFocusableElements(activeController.dialog);
            if (!focusable.length) return;
            const currentIndex = focusable.indexOf(document.activeElement);
            if (event.shiftKey) {
                if (currentIndex <= 0) {
                    event.preventDefault();
                    focusable[focusable.length - 1].focus();
                }
                return;
            }
            if (currentIndex === focusable.length - 1) {
                event.preventDefault();
                focusable[0].focus();
            }
        });

        function register({
            modal,
            dialog,
            closeOnBackdrop = true,
            getInitialFocus,
            beforeClose,
            afterOpen,
            afterClose,
        }) {
            if (!modal || !dialog) {
                return {
                    open() {},
                    close() { return false; },
                    isOpen() { return false; },
                };
            }

            const controller = {
                modal,
                dialog,
                trigger: null,
                closeOnBackdrop,
                open(trigger = document.activeElement) {
                    controller.trigger = trigger instanceof HTMLElement ? trigger : null;
                    modal.classList.remove("hidden");
                    modal.setAttribute("aria-hidden", "false");
                    activeController = controller;
                    lockScroll();
                    window.requestAnimationFrame(() => {
                        const nextFocus = typeof getInitialFocus === "function"
                            ? getInitialFocus()
                            : getFocusableElements(dialog)[0] || dialog;
                        nextFocus?.focus?.();
                    });
                    afterOpen?.();
                },
                close({ force = false, reason = "programmatic" } = {}) {
                    if (!force && beforeClose?.({ reason }) === false) {
                        return false;
                    }
                    modal.classList.add("hidden");
                    modal.setAttribute("aria-hidden", "true");
                    if (activeController === controller) {
                        activeController = null;
                    }
                    unlockScroll();
                    afterClose?.({ reason });
                    controller.trigger?.focus?.();
                    return true;
                },
                isOpen() {
                    return !modal.classList.contains("hidden");
                },
            };

            modal.addEventListener("click", (event) => {
                if (event.target !== modal || !controller.closeOnBackdrop) return;
                controller.close({ reason: "backdrop" });
            });

            return controller;
        }

        return { register };
    }

    const modalManager = createModalManager();
    let healthCheckResultModalController = null;
    let healthCheckResultModalNode = null;

    function wait(ms) {
        return new Promise((resolve) => window.setTimeout(resolve, ms));
    }

    function ensureHealthCheckResultModalController() {
        const modal = document.getElementById("provider-test-result-modal");
        const titleNode = document.getElementById("provider-test-result-modal-title");
        const contentNode = document.getElementById("provider-test-result-modal-content");
        if (!modal || !titleNode || !contentNode) {
            return null;
        }
        if (healthCheckResultModalController && healthCheckResultModalNode === modal) {
            return { controller: healthCheckResultModalController, titleNode, contentNode };
        }
        healthCheckResultModalNode = modal;
        healthCheckResultModalController = modalManager.register({
            modal,
            dialog: modal.querySelector('[role="dialog"]'),
            getInitialFocus: () => document.getElementById("provider-test-result-modal-close"),
            afterClose: () => {
                contentNode.innerHTML = "";
            },
        });
        const closeBtn = document.getElementById("provider-test-result-modal-close");
        if (closeBtn && closeBtn.dataset.boundHealthCheckResultClose !== "true") {
            closeBtn.dataset.boundHealthCheckResultClose = "true";
            closeBtn.addEventListener("click", () => {
                healthCheckResultModalController?.close();
            });
        }
        return { controller: healthCheckResultModalController, titleNode, contentNode };
    }

    function openHealthCheckResultModal(title, html, trigger = document.activeElement) {
        const modalState = ensureHealthCheckResultModalController();
        if (!modalState) return;
        const { controller, titleNode, contentNode } = modalState;
        titleNode.textContent = title;
        contentNode.innerHTML = html;
        if (controller.isOpen()) {
            enhanceInteractiveButtons(contentNode);
            return;
        }
        controller.open(trigger);
        enhanceInteractiveButtons(contentNode);
    }

    function refreshHealthCheckResultModal(title, html) {
        const modalState = ensureHealthCheckResultModalController();
        if (!modalState) return;
        const { controller, titleNode, contentNode } = modalState;
        if (!controller.isOpen()) return;
        titleNode.textContent = title;
        contentNode.innerHTML = html;
        enhanceInteractiveButtons(contentNode);
    }

    function closeHealthCheckResultModal(options = {}) {
        healthCheckResultModalController?.close(options);
    }

    function withJson(method, data, extraHeaders = {}) {
        return {
            method,
            cache: "no-store",
            headers: { "Content-Type": "application/json", "Cache-Control": "no-cache", ...extraHeaders },
            body: JSON.stringify(data ?? {}),
        };
    }

    function matchRoute(pathname, prefix) {
        return pathname === prefix || pathname.startsWith(`${prefix}/`);
    }

    function getRouteRole(pathname) {
        if (PUBLIC_ROUTE_PREFIXES.some((prefix) => matchRoute(pathname, prefix))) {
            return "public";
        }
        if (matchRoute(pathname, "/user")) {
            return "user";
        }
        if (pathname === "/" || ADMIN_ROUTE_PREFIXES.some((prefix) => matchRoute(pathname, prefix))) {
            return "admin";
        }
        return "public";
    }

    function getRoleHomePath(role = authContext.userRole) {
        return role === "user" ? "/user" : "/";
    }

    function buildLoginPath(targetPath = `${window.location.pathname}${window.location.search}`) {
        return `/login?next=${encodeURIComponent(targetPath)}`;
    }

    function resolveRouteRedirect(targetUrl) {
        const target = new URL(targetUrl, window.location.origin);
        const routeRole = getRouteRole(target.pathname);
        if (routeRole === "public") {
            return null;
        }
        if (!authContext.isAuthenticated) {
            return buildLoginPath(`${target.pathname}${target.search}`);
        }
        if (routeRole !== authContext.userRole) {
            return getRoleHomePath();
        }
        return null;
    }

    async function parseResponse(response) {
        const text = await response.text();
        const data = text ? safeJsonParse(text) ?? text : null;
        if (response.status === 401) {
            window.location.href = buildLoginPath();
            throw new Error("登录状态已失效，请重新登录");
        }
        if (response.status === 403 && authContext.isAuthenticated) {
            window.location.href = getRoleHomePath();
            throw new Error("当前账号无权访问该内容");
        }
        if (!response.ok) {
            throw new Error(extractErrorMessage(data));
        }
        return data;
    }

    async function parseErrorResponse(response) {
        const text = await response.text();
        const data = text ? safeJsonParse(text) ?? text : null;
        return extractErrorMessage(data);
    }

    function extractErrorMessage(payload) {
        if (payload && typeof payload === "object") {
            const error = payload.error;
            if (error && typeof error === "object") {
                if (typeof error.message === "string" && error.message.trim()) {
                    return error.message.trim();
                }
                if (typeof error.next_action === "string" && error.next_action.trim()) {
                    return error.next_action.trim();
                }
            }
            if (typeof payload.message === "string" && payload.message.trim()) {
                return payload.message.trim();
            }
            if (typeof payload.detail === "string" && payload.detail.trim()) {
                return payload.detail.trim();
            }
            return JSON.stringify(payload, null, 2);
        }
        if (typeof payload === "string" && payload.trim()) {
            return payload.trim();
        }
        return "请求失败";
    }

    async function streamJsonLines(url, data, onEvent) {
        const response = await fetch(url, withJson("POST", data));
        if (response.status === 401) {
            window.location.href = buildLoginPath();
            throw new Error("登录状态已失效，请重新登录");
        }
        if (response.status === 403 && authContext.isAuthenticated) {
            window.location.href = getRoleHomePath();
            throw new Error("当前账号无权访问该内容");
        }
        if (!response.ok) {
            throw new Error(await parseErrorResponse(response));
        }
        const reader = response.body?.getReader();
        if (!reader) {
            throw new Error("健康检查流式响应不可用");
        }
        const decoder = new TextDecoder();
        let buffer = "";
        while (true) {
            const { value, done } = await reader.read();
            if (done) break;
            buffer += decoder.decode(value, { stream: true });
            let lineBreakIndex = buffer.indexOf("\n");
            while (lineBreakIndex >= 0) {
                const line = buffer.slice(0, lineBreakIndex).trim();
                buffer = buffer.slice(lineBreakIndex + 1);
                if (line) {
                    const payload = safeJsonParse(line);
                    if (payload) {
                        onEvent(payload);
                    }
                }
                lineBreakIndex = buffer.indexOf("\n");
            }
        }
        const tail = buffer.trim();
        if (tail) {
            const payload = safeJsonParse(tail);
            if (payload) {
                onEvent(payload);
            }
        }
    }

    function safeJsonParse(text) {
        try {
            return JSON.parse(text);
        } catch {
            return null;
        }
    }

    function formatLogRawJson(value, maxLength = 20000) {
        const text = JSON.stringify(value || {}, null, 2);
        if (text.length <= maxLength) return text;
        return `${text.slice(0, maxLength)}\n... 已截断，原始长度 ${formatNumber(text.length)} 字符`;
    }

    function syncResponsiveTableLabels(scope = document) {
        const tables = scope.querySelectorAll(".table-shell table, .table-responsive table");
        tables.forEach((table) => {
            const headers = Array.from(table.querySelectorAll("thead th")).map((cell) => cell.textContent.replace(/\s+/g, " ").trim());
            if (!headers.length) return;
            table.querySelectorAll("tbody tr").forEach((row) => {
                const cells = Array.from(row.querySelectorAll("td"));
                cells.forEach((cell, index) => {
                    cell.dataset.label = headers[index] || "";
                });
            });
        });
    }

    let responsiveTableSyncHandle = 0;
    function scheduleResponsiveTableSync(scope = document) {
        if (responsiveTableSyncHandle) {
            window.cancelAnimationFrame(responsiveTableSyncHandle);
        }
        responsiveTableSyncHandle = window.requestAnimationFrame(() => {
            responsiveTableSyncHandle = 0;
            syncResponsiveTableLabels(scope);
        });
    }

    function showToast(message, type = "success") {
        const stack = document.getElementById("toast-stack");
        if (!stack) return;
        while (stack.children.length >= 3) {
            stack.firstElementChild?.remove();
        }
        const node = document.createElement("div");
        node.className = `toast toast-${type}`;
        node.setAttribute("role", "status");
        node.textContent = message;
        stack.appendChild(node);
        setTimeout(() => node.remove(), 2800);
    }

    function showActionToast(message, { type = "success", actionText = "", onAction = null, duration = 5200 } = {}) {
        const stack = document.getElementById("toast-stack");
        if (!stack) return;
        while (stack.children.length >= 3) {
            stack.firstElementChild?.remove();
        }
        const node = document.createElement("div");
        node.className = `toast toast-${type} toast-with-action`;
        node.setAttribute("role", "status");
        const messageNode = document.createElement("span");
        messageNode.textContent = message;
        node.appendChild(messageNode);
        if (actionText && typeof onAction === "function") {
            const button = document.createElement("button");
            button.className = "toast-action-btn";
            button.type = "button";
            button.textContent = actionText;
            button.addEventListener("click", () => {
                window.clearTimeout(Number(node.dataset.toastTimer || 0));
                node.remove();
                onAction();
            });
            node.appendChild(button);
        }
        stack.appendChild(node);
        node.dataset.toastTimer = String(window.setTimeout(() => node.remove(), duration));
    }

    function confirmDangerAction({ title, message, confirmText = "确认" }) {
        return new Promise((resolve) => {
            const modal = document.createElement("div");
            modal.className = "modal-shell";
            modal.setAttribute("aria-hidden", "true");
            modal.innerHTML = `
                <div class="modal-card modal-sm" role="dialog" aria-modal="true" aria-labelledby="danger-confirm-title" tabindex="-1">
                    <div class="modal-head">
                        <h3 id="danger-confirm-title">${escapeHtml(title)}</h3>
                        <button class="icon-btn interactive-btn" type="button" data-confirm-cancel aria-label="关闭确认弹窗">×</button>
                    </div>
                    <div class="modal-body-stack">
                        <p class="table-muted">${escapeHtml(message)}</p>
                        <div class="hero-actions">
                            <button class="btn btn-ghost interactive-btn" type="button" data-confirm-cancel>取消</button>
                            <button class="btn btn-danger-soft interactive-btn" type="button" data-confirm-ok>${escapeHtml(confirmText)}</button>
                        </div>
                    </div>
                </div>
            `;
            document.body.appendChild(modal);
            const dialog = modal.querySelector('[role="dialog"]');
            let settled = false;
            const controller = modalManager.register({
                modal,
                dialog,
                getInitialFocus: () => modal.querySelector("[data-confirm-cancel]"),
                afterClose: () => {
                    if (!settled) {
                        settled = true;
                        resolve(false);
                    }
                    modal.remove();
                },
            });
            const finish = (value) => {
                if (settled) return;
                settled = true;
                resolve(value);
                controller.close({ force: true });
            };
            modal.querySelectorAll("[data-confirm-cancel]").forEach((button) => {
                button.addEventListener("click", () => finish(false));
            });
            modal.querySelector("[data-confirm-ok]")?.addEventListener("click", () => finish(true));
            controller.open();
        });
    }

    function setButtonTransientFeedback(button, status = "success", options = {}) {
        if (!button) return;
        const {
            successText = "已完成",
            errorText = "失败",
            reviewText = "待复核",
            duration = 1400,
        } = options;
        const nextText = status === "error" ? errorText : (status === "review" ? reviewText : successText);
        window.clearTimeout(Number(button.dataset.feedbackTimer || 0));
        if (!button.dataset.feedbackOriginalText) {
            button.dataset.feedbackOriginalText = button.textContent;
        }
        button.classList.remove("is-action-success", "is-action-error", "is-action-review");
        button.classList.add(status === "error" ? "is-action-error" : (status === "review" ? "is-action-review" : "is-action-success"));
        button.textContent = nextText;
        button.dataset.feedbackTimer = String(window.setTimeout(() => {
            button.classList.remove("is-action-success", "is-action-error", "is-action-review");
            button.textContent = button.dataset.feedbackOriginalText || button.textContent;
            delete button.dataset.feedbackTimer;
        }, duration));
    }

    function isHealthCheckUsable(result) {
        const healthStatus = String(result?.health_status || "").trim();
        if (healthStatus === "healthy" || healthStatus === "degraded") return true;
        if (typeof result?.provider_success === "boolean") return result.provider_success;
        return result?.success === true;
    }

    function formatHealthCheckOutcomeLabel(result) {
        if (result?.success) return "成功";
        return isHealthCheckUsable(result) ? "部分可用" : "失败";
    }

    function formatTestResultLabel(result, fallbackName) {
        const statusCode = result?.status_code ?? "-";
        const latencyMs = result?.latency_ms ?? "-";
        const statusText = formatHealthCheckOutcomeLabel(result);
        const healthText = result?.health_status ? `，健康 ${formatHealthStatusLabel(result.health_status)}` : "";
        const providerText = typeof result?.provider_success === "boolean"
            ? `，连通${result.provider_success ? "成功" : "失败"}`
            : "";
        const modelText = Number.isFinite(result?.models_total)
            ? `，模型 ${result.models_success ?? 0}/${result.models_total} 正常`
            : "";
        const message = result?.message ? `，${result.message}` : "";
        return `${fallbackName} 测试${statusText}${providerText}${healthText}，状态码 ${statusCode}，耗时 ${latencyMs} ms${modelText}${message}`;
    }

    function renderEndpointProbeHtml(endpointResults) {
        const items = Array.isArray(endpointResults) ? endpointResults : [];
        if (!items.length) {
            return '<div class="table-muted">未返回正式代理端点测试明细</div>';
        }
        return items.map((item) => `
            <div class="playground-info-row">
                <div class="playground-info-label">${escapeHtml(formatEndpointProbeLabel(item.endpoint_label || item.endpoint_path || "-"))}</div>
                <div class="playground-info-value">
                    ${item.success ? '<span class="playground-status-success">成功</span>' : '<span class="playground-status-danger">失败</span>'}
                    · ${escapeHtml(formatEndpointProbeSupportLabel(item.support_label || formatEndpointSupportMode(item.support_mode)))}
                    · 状态码 ${escapeHtml(String(item.status_code ?? "-"))}
                    · 耗时 ${escapeHtml(String(item.latency_ms ?? "-"))} ms
                    · ${escapeHtml(item.message || "-")}
                </div>
            </div>
        `).join("");
    }

    function formatEndpointProbeLabel(value) {
        const normalized = String(value || "").trim();
        if (!normalized) return "-";
        return ENDPOINT_PROBE_LABELS[normalized] || normalized;
    }

    function formatEndpointProbeSupportLabel(value) {
        const normalized = String(value || "").trim();
        if (!normalized) return "支持状态未知";
        return normalized
            .replaceAll("image_generation", "生图（image_generation）")
            .replaceAll("tools", "工具");
    }

    function formatEndpointSupportMode(mode) {
        if (mode === "native") return "原生支持";
        if (mode === "adapted") return "原生支持";
        if (mode === "unsupported") return "不支持";
        return "支持状态未知";
    }

    function renderProviderTestModalBody(result, options = {}) {
        const scope = options.scope || "provider";
        const titleName = options.name || result?.provider_name || result?.model_name || "测试对象";
        const modelResults = Array.isArray(result?.model_results) ? result.model_results : [];
        const endpointResults = Array.isArray(result?.endpoint_results) ? result.endpoint_results : [];
        const healthLabel = scope === "model" ? "模型健康" : "整体可用性";
        const healthValue = scope === "model"
            ? formatHealthStatusLabel(result?.health_status || "unknown")
            : formatProviderAvailabilityLabel(result?.health_status || "unknown");
        const summaryRows = [
            ["测试对象", titleName],
            ["测试范围", scope === "model" ? "单模型测试" : "提供商测试"],
            ["结果", formatHealthCheckOutcomeLabel(result)],
            [healthLabel, healthValue],
            ["状态码", result?.status_code ?? "-"],
            ["耗时", `${result?.latency_ms ?? "-"} ms`],
        ];
        if (scope === "provider") {
            summaryRows.push(["连通性", result?.provider_success ? "成功" : "失败"]);
            summaryRows.push(["模型通过", `${result?.models_success ?? 0}/${result?.models_total ?? 0}`]);
        }
        const summaryHtml = summaryRows.map(([label, value]) => `
            <div class="provider-test-summary-item">
                <span>${escapeHtml(String(label))}</span>
                <strong>${escapeHtml(String(value))}</strong>
            </div>
        `).join("");
        const messageHtml = escapeHtml(result?.message || "无补充说明");
        const modelHtml = scope === "provider"
            ? (modelResults.length
                ? modelResults.map((item) => `
                    <article class="provider-test-model-item">
                        <div class="provider-test-model-top">
                            <strong>${escapeHtml(item.model_name || "-")}</strong>
                            <div>${statusBadge(item.health_status || "unknown")}</div>
                        </div>
                        <div class="table-muted">状态码 ${item.status_code ?? "-"} · 耗时 ${item.latency_ms ?? "-"} ms</div>
                        <div class="provider-test-model-message">${escapeHtml(item.message || "-")}</div>
                        <div class="provider-test-model-message">${renderEndpointProbeHtml(item.endpoint_results)}</div>
                    </article>
                `).join("")
                : '<div class="empty-state">当前提供商没有可展示的模型测试结果</div>')
            : "";
        return `
            <div class="provider-test-result-shell">
                <section class="provider-test-result-card">
                    <div class="panel-kicker">测试摘要</div>
                    <div class="provider-test-summary-grid">${summaryHtml}</div>
                </section>
                <section class="provider-test-result-card">
                    <div class="panel-kicker">结果说明</div>
                    <div class="provider-test-message">${messageHtml}</div>
                </section>
                <section class="provider-test-result-card">
                    <div class="panel-kicker">端点结果</div>
                    <div class="provider-test-model-message">${renderEndpointProbeHtml(endpointResults)}</div>
                </section>
                ${scope === "provider" ? `
                <section class="provider-test-result-card">
                    <div class="panel-kicker">模型结果</div>
                    <div class="provider-test-model-list">${modelHtml}</div>
                </section>
                ` : ""}
            </div>
        `;
    }

    function createHealthCheckStreamState(scope, title) {
        return {
            scope,
            title,
            running: true,
            currentProviderName: "",
            currentStageLabel: "准备开始",
            stages: [],
            providerSummaries: [],
            finalResult: null,
            errorMessage: "",
        };
    }

    function applyHealthCheckStreamEvent(state, event) {
        if (event.event === "provider_started") {
            state.currentProviderName = event.provider_name || "";
            state.currentStageLabel = `正在准备 ${event.provider_name || "当前提供商"} 的健康检查`;
            return;
        }
        if (event.event === "stage_started") {
            state.currentProviderName = event.provider_name || state.currentProviderName;
            state.currentStageLabel = `${event.provider_name || "当前提供商"} · ${event.phase_label || event.phase_key || "检查中"}`;
            return;
        }
        if (event.event === "stage_completed") {
            const successCount = Number(event.success_count || 0);
            const failureCount = Number(event.failure_count || 0);
            state.stages.push({
                providerName: event.provider_name || state.currentProviderName || "当前提供商",
                phaseLabel: event.phase_label || event.phase_key || "检查阶段",
                skipped: event.skipped === true,
                modelTotal: Number(event.model_total || 0),
                successCount,
                failureCount,
            });
            state.currentStageLabel = event.skipped
                ? `${event.provider_name || state.currentProviderName || "当前提供商"} · ${event.phase_label || "检查阶段"}已跳过`
                : `${event.provider_name || state.currentProviderName || "当前提供商"} · ${event.phase_label || "检查阶段"}已完成`;
            return;
        }
        if (event.event === "provider_completed") {
            state.providerSummaries.push({
                providerName: event.provider_name || "当前提供商",
                success: event.success === true,
                modelsTotal: Number(event.models_total || 0),
                modelsSuccess: Number(event.models_success || 0),
                modelsFailed: Number(event.models_failed || 0),
            });
            return;
        }
        if (event.event === "completed") {
            state.running = false;
            state.finalResult = event.result;
            state.currentStageLabel = "全部检查已完成";
            return;
        }
        if (event.event === "error") {
            state.running = false;
            state.errorMessage = event.message || "健康检查执行失败";
        }
    }

    function renderHealthCheckStageList(stages = []) {
        if (!stages.length) {
            return '<div class="empty-state">当前还没有完成的阶段结果。</div>';
        }
        return stages.map((item) => `
            <article class="provider-test-model-item">
                <div class="provider-test-model-top">
                    <strong>${escapeHtml(item.providerName)}</strong>
                    <div>${item.skipped ? statusBadge("skipped") : statusBadge(item.successCount > 0 ? (item.failureCount > 0 ? "degraded" : "healthy") : "unhealthy")}</div>
                </div>
                <div class="table-muted">${escapeHtml(item.phaseLabel)}</div>
                <div class="provider-test-model-message">
                    ${item.skipped
                        ? "当前阶段无可执行模型，已跳过。"
                        : `共 ${formatNumber(item.modelTotal)} 个模型，成功 ${formatNumber(item.successCount)} 个，失败 ${formatNumber(item.failureCount)} 个。`}
                </div>
            </article>
        `).join("");
    }

    function renderHealthCheckProviderSummaryList(items = []) {
        if (!items.length) {
            return '<div class="empty-state">当前还没有可展示的提供商结果。</div>';
        }
        return items.map((item) => `
            <article class="provider-test-model-item">
                <div class="provider-test-model-top">
                    <strong>${escapeHtml(item.providerName)}</strong>
                    <div>${statusBadge(item.success ? "healthy" : (item.modelsSuccess > 0 ? "degraded" : "unhealthy"))}</div>
                </div>
                <div class="provider-test-model-message">
                    模型通过 ${formatNumber(item.modelsSuccess)}/${formatNumber(item.modelsTotal)}，失败 ${formatNumber(item.modelsFailed)} 个。
                </div>
            </article>
        `).join("");
    }

    function renderHealthCheckStreamModalBody(state) {
        const providerResultItems = Array.isArray(state.finalResult)
            ? state.finalResult.filter((item) => item.scope === "provider")
            : [];
        const successCount = providerResultItems.filter((item) => item.success).length;
        const totalCount = providerResultItems.length;
        const summaryRows = [
            ["检查范围", state.scope === "all" ? "全部提供商" : "单提供商"],
            ["执行状态", state.errorMessage ? "失败" : (state.running ? "执行中" : "已完成")],
            ["当前阶段", state.currentStageLabel || "准备开始"],
        ];
        if (state.scope === "all" && totalCount > 0) {
            summaryRows.push(["提供商通过", `${formatNumber(successCount)}/${formatNumber(totalCount)}`]);
        }
        const summaryHtml = summaryRows.map(([label, value]) => `
            <div class="provider-test-summary-item">
                <span>${escapeHtml(String(label))}</span>
                <strong>${escapeHtml(String(value))}</strong>
            </div>
        `).join("");
        const progressHtml = `
            <div class="provider-test-result-shell">
                <section class="provider-test-result-card">
                    <div class="panel-kicker">执行进度</div>
                    <div class="provider-test-summary-grid">${summaryHtml}</div>
                </section>
                <section class="provider-test-result-card">
                    <div class="panel-kicker">阶段反馈</div>
                    <div class="provider-test-model-list">${renderHealthCheckStageList(state.stages)}</div>
                </section>
                ${state.scope === "all" ? `
                <section class="provider-test-result-card">
                    <div class="panel-kicker">提供商结果</div>
                    <div class="provider-test-model-list">${renderHealthCheckProviderSummaryList(
                        state.providerSummaries.length ? state.providerSummaries : providerResultItems.map((item) => ({
                            providerName: item.provider_name || "-",
                            success: item.success === true,
                            modelsTotal: Number(item.models_total || 0),
                            modelsSuccess: Number(item.models_success || 0),
                            modelsFailed: Number(item.models_failed || 0),
                        }))
                    )}</div>
                </section>
                ` : ""}
            </div>
        `;
        if (state.errorMessage) {
            return `${progressHtml}
                <section class="provider-test-result-card">
                    <div class="panel-kicker">错误信息</div>
                    <div class="provider-test-message">${escapeHtml(state.errorMessage)}</div>
                </section>
            `;
        }
        if (state.scope === "provider" && state.finalResult && !Array.isArray(state.finalResult)) {
            return `${progressHtml}${renderProviderTestModalBody(state.finalResult, { scope: "provider", name: state.title })}`;
        }
        return progressHtml;
    }

    async function runHealthCheckStream(options) {
        const {
            url,
            title,
            scope,
            trigger,
            showModal = true,
            onCompleted = null,
            data = {},
        } = options;
        const state = createHealthCheckStreamState(scope, title);
        if (showModal) {
            openHealthCheckResultModal(title, renderHealthCheckStreamModalBody(state), trigger);
        }
        await streamJsonLines(url, data, (event) => {
            applyHealthCheckStreamEvent(state, event);
            if (showModal) {
                openHealthCheckResultModal(title, renderHealthCheckStreamModalBody(state), trigger);
            }
        });
        if (state.errorMessage) {
            throw new Error(state.errorMessage);
        }
        if (typeof onCompleted === "function") {
            await onCompleted(state.finalResult);
        }
        return state.finalResult;
    }

    function openTestFeaturePicker(options = {}) {
        const title = options.title || "选择测试功能";
        const description = options.description || "默认只测试流式链路；可按需追加其它能力。";
        const featureOptions = [
            { value: "text_stream", label: "流式", detail: "验证流式输出链路", checked: true },
            { value: "vision", label: "图片", detail: "验证图片输入能力，不生成图片" },
            { value: "tools", label: "工具", detail: "验证原生 tools/function calling" },
            { value: "image_generation", label: "生图", detail: "验证 image_generation 生图结果" },
        ];
        return new Promise((resolve) => {
            const modal = document.createElement("div");
            modal.className = "modal-shell";
            modal.setAttribute("aria-hidden", "false");
            modal.innerHTML = `
                <div class="modal-card provider-modal-card" role="dialog" aria-modal="true" aria-labelledby="test-feature-picker-title" tabindex="-1">
                    <div class="modal-head">
                        <div>
                            <div class="panel-kicker">测试范围</div>
                            <h2 id="test-feature-picker-title">${escapeHtml(title)}</h2>
                        </div>
                        <button class="icon-btn interactive-btn" data-test-feature-close type="button" aria-label="关闭测试功能选择">×</button>
                    </div>
                    <div class="modal-body-stack">
                        <p class="table-muted">${escapeHtml(description)}</p>
                        <div class="settings-switch-grid">
                            ${featureOptions.map((item) => `
                                <label class="settings-switch-card">
                                    <span class="settings-switch-copy">
                                        <strong>${escapeHtml(item.label)}</strong>
                                        <small>${escapeHtml(item.detail)}</small>
                                    </span>
                                    <span class="settings-switch-control">
                                        <input type="checkbox" value="${escapeHtml(item.value)}" data-test-feature-option ${item.checked ? "checked" : ""}>
                                        <span class="settings-switch-slider"></span>
                                    </span>
                                </label>
                            `).join("")}
                        </div>
                    </div>
                    <div class="form-actions">
                        <button class="btn btn-ghost interactive-btn" data-test-feature-cancel type="button">取消</button>
                        <button class="btn btn-accent interactive-btn" data-test-feature-confirm type="button">开始测试</button>
                    </div>
                </div>
            `;
            document.body.appendChild(modal);
            const card = modal.querySelector(".modal-card");
            const cleanup = (value) => {
                modal.remove();
                resolve(value);
            };
            modal.querySelector("[data-test-feature-close]")?.addEventListener("click", () => cleanup(null));
            modal.querySelector("[data-test-feature-cancel]")?.addEventListener("click", () => cleanup(null));
            modal.addEventListener("click", (event) => {
                if (event.target === modal) cleanup(null);
            });
            modal.querySelector("[data-test-feature-confirm]")?.addEventListener("click", () => {
                const selected = Array.from(modal.querySelectorAll("[data-test-feature-option]:checked")).map((item) => item.value);
                if (!selected.length) {
                    showToast("请至少选择一项测试功能", "error");
                    return;
                }
                cleanup(selected);
            });
            enhanceInteractiveButtons(modal);
            card?.focus();
        });
    }

    function setBatchPlaceholder(message) {
        const empty = document.getElementById("playground-batch-output-empty");
        const output = document.getElementById("playground-batch-output");
        if (!empty || !output) return;
        empty.textContent = message;
        empty.classList.remove("hidden");
        output.classList.add("hidden");
        output.innerHTML = "";
    }

    function showBatchRendered(html) {
        const empty = document.getElementById("playground-batch-output-empty");
        const output = document.getElementById("playground-batch-output");
        if (!empty || !output) return;
        empty.classList.add("hidden");
        output.classList.remove("hidden");
        output.innerHTML = html;
    }

    const PRICE_PER_1M_MULTIPLIER = 1000;

    function toPricePer1M(value) {
        if (value == null || Number.isNaN(Number(value))) return null;
        return Number(value) * PRICE_PER_1M_MULTIPLIER;
    }

    function toPricePer1K(value) {
        if (value == null || Number.isNaN(Number(value))) return null;
        return Number(value) / PRICE_PER_1M_MULTIPLIER;
    }

    function collectConfiguredModels(providers = [], options = {}) {
        const {
            requireStream = false,
            requireVision = false,
            requireImageGeneration = false,
            allowedModelNameSet = null,
        } = options;
        const seen = new Set();
        const models = [];
        providers
            .filter((provider) => provider.enabled)
            .forEach((provider) => {
                (provider.model_configs || []).forEach((modelConfig) => {
                    if (!modelConfig?.enabled || !modelConfig.model_name) return;
                    if (allowedModelNameSet && !allowedModelNameSet.has(modelConfig.model_name)) return;
                    if (requireStream && !modelConfig.supports_stream) return;
                    if (requireVision && !modelConfig.supports_vision) return;
                    if (requireImageGeneration && !supportsImageGeneration(modelConfig)) return;
                    if (seen.has(modelConfig.model_name)) return;
                    seen.add(modelConfig.model_name);
                    models.push(modelConfig.model_name);
                });
            });
        return models.sort((a, b) => a.localeCompare(b, "zh-CN"));
    }

    function collectProviderConfiguredModels(provider, options = {}) {
        const {
            requireStream = false,
            requireVision = false,
            requireImageGeneration = false,
            allowedModelNameSet = null,
        } = options;
        if (!provider?.enabled) return [];
        return (provider.model_configs || [])
            .filter((modelConfig) => (
                modelConfig?.enabled
                && modelConfig.model_name
                && (!allowedModelNameSet || allowedModelNameSet.has(modelConfig.model_name))
                && (!requireStream || modelConfig.supports_stream)
                && (!requireVision || modelConfig.supports_vision)
                && (!requireImageGeneration || supportsImageGeneration(modelConfig))
            ))
            .map((modelConfig) => modelConfig.model_name)
            .sort((a, b) => a.localeCompare(b, "zh-CN"));
    }

    function supportsImageGeneration(modelConfig) {
        if (!modelConfig || typeof modelConfig !== "object") return false;
        return modelConfig.supports_image_generation === true;
    }

    const MODEL_MANAGEMENT_CAPABILITY_TEXT = "流式、工具、图片";
