    function formatSwitchText(value, enabledLabel = "开启", disabledLabel = "关闭") {
        return value ? enabledLabel : disabledLabel;
    }

    function formatMoney(value) {
        if (value == null || Number.isNaN(Number(value))) return "不限";
        return `${formatAdaptiveDecimal(value, { maxDecimals: 9 })} $`;
    }

    function formatPrice(value) {
        if (value == null || Number.isNaN(Number(value))) return "-";
        return `${formatAdaptiveDecimal(toPricePer1M(value), { maxDecimals: 9 })} $/1M`;
    }

    function formatMultiplier(value) {
        if (value == null || Number.isNaN(Number(value))) return "1x";
        return `${Number(value).toFixed(2)}x`;
    }

    function toFiniteNumber(value) {
        const numeric = Number(value);
        return Number.isFinite(numeric) ? numeric : null;
    }

    function trimTrailingZeros(value) {
        return String(value).replace(/(?:\.0+|(\.\d*?[1-9])0+)$/, "$1");
    }

    function formatAdaptiveDecimal(value, options = {}) {
        const {
            minDecimals = 0,
            maxDecimals = 9,
            fallback = "-",
        } = options;
        const numeric = toFiniteNumber(value);
        if (numeric == null) return fallback;
        const absolute = Math.abs(numeric);
        if (absolute === 0) {
            return Number(0).toFixed(minDecimals);
        }
        let decimals = maxDecimals;
        if (absolute >= 1000) {
            decimals = Math.min(maxDecimals, Math.max(minDecimals, 2));
        } else if (absolute >= 1) {
            decimals = Math.min(maxDecimals, Math.max(minDecimals, 6));
        }
        const fixed = numeric.toFixed(decimals);
        return decimals === minDecimals ? fixed : trimTrailingZeros(fixed);
    }

    function roundCurrency(value, decimals = 9) {
        return value == null || Number.isNaN(Number(value)) ? null : Number(Number(value).toFixed(decimals));
    }

    function formatTokenDisplay(value) {
        const numeric = toFiniteNumber(value);
        if (numeric == null) return "-";
        const tokenValue = Math.max(0, numeric);
        if (tokenValue < 1000) {
            return `${formatNumber(Math.round(tokenValue))} token`;
        }
        if (tokenValue < 1000000) {
            return `${(tokenValue / 1000).toFixed(2)}k`;
        }
        return `${(tokenValue / 1000000).toFixed(2)}m`;
    }

    function formatUsdValue(value) {
        const numeric = toFiniteNumber(value);
        if (numeric == null) return "-";
        return `${formatAdaptiveDecimal(numeric, { maxDecimals: 9, fallback: "0" })} $`;
    }

    function formatUsdPer1M(value) {
        const numeric = toFiniteNumber(value);
        if (numeric == null) return "未设置";
        return `${formatAdaptiveDecimal(numeric * 1000, { maxDecimals: 12, fallback: "0" })} $/1M`;
    }

    function sumCosts(...values) {
        const numbers = values.map((value) => toFiniteNumber(value)).filter((value) => value != null);
        if (!numbers.length) return null;
        return roundCurrency(numbers.reduce((sum, value) => sum + value, 0));
    }

    function buildBillingBreakdown(log) {
        const multiplierValue = toFiniteNumber(log?.billing_multiplier);
        const multiplier = multiplierValue != null && multiplierValue > 0 ? multiplierValue : 1;
        const inputPrice = toFiniteNumber(log?.channel_price_input_per_1k);
        const outputPrice = toFiniteNumber(log?.channel_price_output_per_1k);
        const cachePrice = toFiniteNumber(log?.channel_price_cache_per_1k) ?? inputPrice;
        const cacheWritePrice = toFiniteNumber(log?.channel_price_cache_write_per_1k) ?? inputPrice;
        const promptTokens = Math.max(0, toFiniteNumber(log?.prompt_tokens) ?? 0);
        const completionTokens = Math.max(0, toFiniteNumber(log?.completion_tokens) ?? 0);
        const totalTokens = Math.max(0, toFiniteNumber(log?.total_tokens) ?? (promptTokens + completionTokens));
        const cacheReadTokens = Math.max(0, toFiniteNumber(log?.cache_read_tokens) ?? 0);
        const cacheWriteTokens = Math.max(0, toFiniteNumber(log?.cache_write_tokens) ?? 0);
        const regularPromptTokens = Math.max(0, promptTokens - cacheReadTokens - cacheWriteTokens);
        const missingInputPrice = regularPromptTokens > 0 && inputPrice == null;
        const missingCacheReadPrice = cacheReadTokens > 0 && cachePrice == null;
        const missingCacheWritePrice = cacheWriteTokens > 0 && cacheWritePrice == null;
        const missingOutputPrice = completionTokens > 0 && outputPrice == null;
        const promptPriceMissing = missingInputPrice || missingCacheReadPrice || missingCacheWritePrice;
        const inputCost = missingInputPrice || inputPrice == null ? null : roundCurrency((regularPromptTokens / 1000) * inputPrice, 9);
        const cacheReadCost = missingCacheReadPrice || cachePrice == null ? null : roundCurrency((cacheReadTokens / 1000) * cachePrice, 9);
        const cacheWriteCost = missingCacheWritePrice || cacheWritePrice == null ? null : roundCurrency((cacheWriteTokens / 1000) * cacheWritePrice, 9);
        const outputCost = missingOutputPrice || outputPrice == null ? null : roundCurrency((completionTokens / 1000) * outputPrice, 9);
        const promptCost = roundCurrency(log?.prompt_cost) ?? (promptPriceMissing ? null : sumCosts(inputCost, cacheReadCost, cacheWriteCost));
        const completionCost = roundCurrency(log?.completion_cost) ?? (missingOutputPrice ? null : outputCost);
        const totalCost = roundCurrency(log?.total_cost) ?? ((promptPriceMissing || missingOutputPrice) ? null : sumCosts(promptCost, completionCost));
        const baseInputPrice = inputPrice == null ? null : roundCurrency(inputPrice / multiplier, 12);
        const baseOutputPrice = outputPrice == null ? null : roundCurrency(outputPrice / multiplier, 12);
        const baseCachePrice = cachePrice == null ? null : roundCurrency(cachePrice / multiplier, 12);
        const baseCacheWritePrice = cacheWritePrice == null ? null : roundCurrency(cacheWritePrice / multiplier, 12);
        return {
            multiplier,
            totalTokens,
            promptTokens,
            completionTokens,
            cacheReadTokens,
            cacheWriteTokens,
            regularPromptTokens,
            inputPrice,
            outputPrice,
            cachePrice,
            cacheWritePrice,
            baseInputPrice,
            baseOutputPrice,
            baseCachePrice,
            baseCacheWritePrice,
            inputCost,
            cacheReadCost,
            cacheWriteCost,
            outputCost,
            promptCost,
            completionCost,
            totalCost,
        };
    }

    function renderBillingTooltip(log) {
        const billing = buildBillingBreakdown(log);
        const originalPriceLines = [
            `输入 ${formatUsdPer1M(billing.baseInputPrice)}`,
            `输出 ${formatUsdPer1M(billing.baseOutputPrice)}`,
            `缓存 ${formatUsdPer1M(billing.baseCachePrice)}`,
            `缓存写 ${formatUsdPer1M(billing.baseCacheWritePrice)}`,
        ];
        const channelPriceLines = [
            `输入 ${formatUsdPer1M(billing.inputPrice)}`,
            `输出 ${formatUsdPer1M(billing.outputPrice)}`,
            `缓存 ${formatUsdPer1M(billing.cachePrice)}`,
            `缓存写 ${formatUsdPer1M(billing.cacheWritePrice)}`,
        ];
        const calculationLines = [
            `输入成本 ${formatTokenDisplay(billing.regularPromptTokens)} × ${formatUsdPer1M(billing.inputPrice)} = ${formatUsdValue(billing.inputCost)}`,
            `缓存读成本 ${formatTokenDisplay(billing.cacheReadTokens)} × ${formatUsdPer1M(billing.cachePrice)} = ${formatUsdValue(billing.cacheReadCost)}`,
            `缓存写成本 ${formatTokenDisplay(billing.cacheWriteTokens)} × ${formatUsdPer1M(billing.cacheWritePrice)} = ${formatUsdValue(billing.cacheWriteCost)}`,
            `输出成本 ${formatTokenDisplay(billing.completionTokens)} × ${formatUsdPer1M(billing.outputPrice)} = ${formatUsdValue(billing.outputCost)}`,
            `总成本 = ${formatUsdValue(billing.totalCost)}，倍率 ${formatMultiplier(billing.multiplier)}`,
        ];
        return `
            <div class="log-billing-tooltip-group">
                <strong>原始模型价格</strong>
                ${originalPriceLines.map((line) => `<div>${escapeHtml(line)}</div>`).join("")}
            </div>
            <div class="log-billing-tooltip-group">
                <strong>提供商价格</strong>
                ${channelPriceLines.map((line) => `<div>${escapeHtml(line)}</div>`).join("")}
            </div>
            <div class="log-billing-tooltip-group">
                <strong>计算过程</strong>
                ${calculationLines.map((line) => `<div>${escapeHtml(line)}</div>`).join("")}
            </div>
        `;
    }

    function renderLogBillingCell(log) {
        const billing = buildBillingBreakdown(log);
        return `
            <div class="log-billing-cell">
                <div class="log-billing-row log-billing-row-primary">
                    <div class="log-billing-pair">
                        <span class="log-billing-label">总成本</span>
                        <strong class="log-billing-total-cost">${escapeHtml(formatUsdValue(billing.totalCost))}</strong>
                    </div>
                    <div class="log-billing-pair">
                        <span class="log-billing-label">总 Token</span>
                        <strong class="log-billing-total-tokens">${escapeHtml(formatTokenDisplay(billing.totalTokens))}</strong>
                    </div>
                    <span class="log-billing-help">
                        <button class="log-billing-help-btn" type="button" aria-label="查看价格与计算过程" data-billing-tooltip-trigger="true">
                            <i class="bi bi-question-circle" aria-hidden="true"></i>
                        </button>
                        <div class="log-billing-tooltip-content hidden">
                            ${renderBillingTooltip(log)}
                        </div>
                    </span>
                </div>
                <div class="log-billing-row">
                    <div class="log-billing-pair">
                        <span class="log-billing-label">输入</span>
                        <span class="log-billing-meta">${escapeHtml(formatTokenDisplay(billing.regularPromptTokens))}</span>
                    </div>
                    <div class="log-billing-pair">
                        <span class="log-billing-label">输出</span>
                        <span class="log-billing-meta">${escapeHtml(formatTokenDisplay(billing.completionTokens))}</span>
                    </div>
                </div>
                <div class="log-billing-row">
                    <div class="log-billing-pair">
                        <span class="log-billing-label">缓存读</span>
                        <span class="log-billing-meta">${escapeHtml(formatTokenDisplay(billing.cacheReadTokens))}</span>
                    </div>
                    <div class="log-billing-pair">
                        <span class="log-billing-label">缓存写</span>
                        <span class="log-billing-meta">${escapeHtml(formatTokenDisplay(billing.cacheWriteTokens))}</span>
                    </div>
                </div>
                <div class="log-billing-row log-billing-row-multiplier">
                    <div class="log-billing-pair">
                        <span class="log-billing-label">倍率</span>
                        <span class="log-billing-multiplier">${escapeHtml(formatMultiplier(billing.multiplier))}</span>
                    </div>
                </div>
            </div>
        `;
    }

    function normalizeLogModelValue(value) {
        if (typeof value !== "string") return "";
        return value.trim();
    }

    function renderLogModelCell(log = {}) {
        const requestedModel = normalizeLogModelValue(log.requested_model);
        const actualModel = normalizeLogModelValue(log.model_name);
        if (!requestedModel && !actualModel) return '<span class="table-muted">-</span>';
        return `
            <div class="log-model-cell">
                <div class="table-muted">原始：${escapeHtml(requestedModel || "-")}</div>
                <strong>实际：${escapeHtml(actualModel || "-")}</strong>
            </div>
        `;
    }

    function buildLogExceptionReason(log = {}) {
        const detailLines = [];
        const message = String(log.message || "").trim();
        const errorCode = String(log.error_code || "").trim();
        const errorType = String(log.error_type || "").trim();
        const contentGuardReason = String(log.content_guard_reason || "").trim();
        const contentGuardExcerpt = String(log.content_guard_excerpt || "").trim();
        const responseText = String(log.response_text || "").trim();
        const billingError = String(log.billing_error || "").trim();
        const tokenFinalizeError = String(log.token_finalize_error || "").trim();
        const authResult = String(log.api_client_auth_result || "").trim();
        if (errorCode) detailLines.push(`错误码：${errorCode}`);
        if (errorType) detailLines.push(`错误类型：${errorType}`);
        if (authResult && authResult !== "authenticated") {
            detailLines.push(`鉴权结果：${formatApiClientAuthResultLabel(authResult)}`);
        }
        if (message && (!log.success || /fail|error|timeout|exceed|invalid/i.test(message))) {
            detailLines.push(`主信息：${message}`);
        }
        if (contentGuardReason) detailLines.push(`内容检测：${contentGuardReason}`);
        if (contentGuardExcerpt) detailLines.push(`命中片段：${contentGuardExcerpt}`);
        if (!detailLines.length && !log.success && responseText) {
            detailLines.push(`响应内容：${responseText}`);
        }
        if (billingError) detailLines.push(`计费补全：${billingError}`);
        if (tokenFinalizeError) detailLines.push(`Token 补全：${tokenFinalizeError}`);
        return Array.from(new Set(detailLines)).filter(Boolean).join("\n");
    }

    function formatLogCellMetricValue(value, suffix = "") {
        if (value == null || Number.isNaN(Number(value))) return "-";
        return `${formatNumber(Number(value))}${suffix}`;
    }

    function formatRequestModalityLabel(value) {
        switch ((value || "").toLowerCase()) {
            case "text":
                return "文本";
            case "vision":
                return "识图";
            case "image_generation":
                return "生图";
            case "image_edit":
                return "图片编辑";
            case "mixed":
                return "混合";
            default:
                return value || "";
        }
    }

    function buildLogModeSummary(log = {}) {
        const parts = [];
        const modalityLabel = formatRequestModalityLabel(log.request_modality);
        if (modalityLabel) parts.push(modalityLabel);
        if (typeof log.generated_images_count === "number" && log.generated_images_count > 0) {
            parts.push(`生成 ${log.generated_images_count} 张`);
        }
        if (log.upstream_usage_missing === true) {
            parts.push("上游未返回 usage");
        }
        return parts.join(" · ");
    }

    function buildContentGuardSummary(log = {}) {
        if (!log.content_guard_result && !log.content_guard_risk_level) return "";
        const parts = [
            `检测 ${formatContentGuardResultLabel(log.content_guard_result)}`,
            `风险 ${formatContentGuardRiskLabel(log.content_guard_risk_level)}`,
        ];
        if (log.content_guard_action) {
            parts.push(`动作 ${formatContentGuardActionLabel(log.content_guard_action)}`);
        }
        return parts.filter(Boolean).join(" · ");
    }

    function renderLogResultCell(log = {}) {
        const modeSummary = buildLogModeSummary(log);
        const contentGuardSummary = buildContentGuardSummary(log);
        return `
            <div class="log-result-cell">
                ${renderStatusWithErrorHint(log.success ? "healthy" : "unhealthy", buildLogExceptionReason(log))}
                <div class="table-muted">HTTP ${log.status_code ?? "-"} · 尝试 ${formatLogCellMetricValue(log.attempt_count)}</div>
                ${modeSummary ? `<div class="table-muted">${escapeHtml(modeSummary)}</div>` : ""}
                ${contentGuardSummary ? `<div class="table-muted">${escapeHtml(contentGuardSummary)}</div>` : ""}
            </div>
        `;
    }

    function formatBillingCalculation(log) {
        const billing = buildBillingBreakdown(log);
        return [
            `原始价格：输入 ${formatUsdPer1M(billing.baseInputPrice)}，输出 ${formatUsdPer1M(billing.baseOutputPrice)}，缓存 ${formatUsdPer1M(billing.baseCachePrice)}`,
            `提供商价格：输入 ${formatUsdPer1M(billing.inputPrice)}，输出 ${formatUsdPer1M(billing.outputPrice)}，缓存 ${formatUsdPer1M(billing.cachePrice)}`,
            `计算：输入 ${formatTokenDisplay(billing.regularPromptTokens)} -> ${formatUsdValue(billing.inputCost)}；缓存读 ${formatTokenDisplay(billing.cacheReadTokens)} -> ${formatUsdValue(billing.cacheReadCost)}；输出 ${formatTokenDisplay(billing.completionTokens)} -> ${formatUsdValue(billing.outputCost)}`,
            `总成本 ${formatUsdValue(billing.totalCost)}；倍率 ${formatMultiplier(billing.multiplier)}`,
        ].join("；");
    }

    let helpTooltipLayer = null;
    let helpTooltipOwner = null;
    let helpTooltipConfig = null;
    const HELP_TOOLTIP_VIEWPORT_PADDING = 12;
    const HELP_TOOLTIP_GAP = 12;
    const HELP_TOOLTIP_CONFIGS = [
        {
            name: "billing",
            triggerSelector: "[data-billing-tooltip-trigger='true']",
            wrapperSelector: ".log-billing-help",
            contentSelector: ".log-billing-tooltip-content",
        },
        {
            name: "provider-status",
            triggerSelector: "[data-provider-status-tooltip-trigger='true']",
            wrapperSelector: ".provider-status-help",
            contentSelector: ".provider-status-tooltip-content",
        },
        {
            name: "settings",
            triggerSelector: "[data-settings-tooltip-trigger='true']",
            wrapperSelector: ".settings-help",
            contentSelector: ".settings-tooltip-content",
            render(trigger, wrapper) {
                const content = wrapper?.querySelector(".settings-tooltip-content");
                if (content) return content.innerHTML;
                const title = trigger.dataset.settingsTooltipTitle || "";
                const copy = trigger.dataset.settingsTooltipCopy || "";
                if (!copy) return "";
                return `
                    ${title ? `<div class="help-tooltip-title">${escapeHtml(title)}</div>` : ""}
                    <div class="help-tooltip-copy">${escapeHtml(copy)}</div>
                `;
            },
        },
    ];

    function ensureHelpTooltipLayer() {
        if (helpTooltipLayer) return helpTooltipLayer;
        helpTooltipLayer = document.createElement("div");
        helpTooltipLayer.id = "help-floating-tooltip";
        helpTooltipLayer.className = "help-tooltip help-tooltip-floating hidden";
        helpTooltipLayer.setAttribute("role", "tooltip");
        document.body.appendChild(helpTooltipLayer);
        return helpTooltipLayer;
    }

    function prepareSettingsTooltipTriggers(scope = document) {
        scope.querySelectorAll(".settings-help-btn[title]").forEach((trigger) => {
            const copy = trigger.getAttribute("title") || "";
            if (!copy) return;
            trigger.dataset.settingsTooltipTrigger = "true";
            trigger.dataset.settingsTooltipTitle = trigger.getAttribute("aria-label") || "说明";
            trigger.dataset.settingsTooltipCopy = copy;
            trigger.removeAttribute("title");
        });
    }

    function findHelpTooltipConfig(trigger) {
        return HELP_TOOLTIP_CONFIGS.find((config) => trigger.matches(config.triggerSelector)) || null;
    }

    function resolveHelpTooltipMarkup(trigger, config) {
        if (!config) return "";
        const wrapper = trigger.closest(config.wrapperSelector);
        if (typeof config.render === "function") {
            return config.render(trigger, wrapper);
        }
        const content = wrapper?.querySelector(config.contentSelector);
        return content?.innerHTML || "";
    }

    function hideHelpTooltip() {
        const tooltip = ensureHelpTooltipLayer();
        tooltip.classList.add("hidden");
        tooltip.innerHTML = "";
        delete tooltip.dataset.placement;
        delete tooltip.dataset.xPlacement;
        helpTooltipOwner = null;
        helpTooltipConfig = null;
    }

    function positionHelpTooltip(trigger) {
        if (!trigger) return;
        const tooltip = ensureHelpTooltipLayer();
        const triggerRect = trigger.getBoundingClientRect();
        const tooltipRect = tooltip.getBoundingClientRect();
        let top = triggerRect.top - tooltipRect.height - HELP_TOOLTIP_GAP;
        let placement = "top";
        if (top < HELP_TOOLTIP_VIEWPORT_PADDING) {
            top = Math.min(
                window.innerHeight - tooltipRect.height - HELP_TOOLTIP_VIEWPORT_PADDING,
                triggerRect.bottom + HELP_TOOLTIP_GAP
            );
            placement = "bottom";
        }
        let left = triggerRect.right + HELP_TOOLTIP_GAP;
        let xPlacement = "right";
        if (left + tooltipRect.width > window.innerWidth - HELP_TOOLTIP_VIEWPORT_PADDING) {
            left = triggerRect.right - tooltipRect.width;
            xPlacement = "left";
        }
        left = Math.max(
            HELP_TOOLTIP_VIEWPORT_PADDING,
            Math.min(left, window.innerWidth - tooltipRect.width - HELP_TOOLTIP_VIEWPORT_PADDING)
        );
        tooltip.style.top = `${top}px`;
        tooltip.style.left = `${left}px`;
        tooltip.dataset.placement = placement;
        tooltip.dataset.xPlacement = xPlacement;
    }

    function showHelpTooltip(trigger) {
        const config = findHelpTooltipConfig(trigger);
        if (!config) return;
        const markup = resolveHelpTooltipMarkup(trigger, config);
        if (!markup) return;
        const tooltip = ensureHelpTooltipLayer();
        helpTooltipOwner = trigger;
        helpTooltipConfig = config;
        tooltip.innerHTML = markup;
        tooltip.classList.remove("hidden");
        positionHelpTooltip(trigger);
    }

    function getHelpTooltipScope(target) {
        if (!(target instanceof Element)) return null;
        for (const config of HELP_TOOLTIP_CONFIGS) {
            const wrapper = target.closest(config.wrapperSelector);
            if (wrapper) return wrapper;
            const trigger = target.closest(config.triggerSelector);
            if (trigger) return trigger;
        }
        return null;
    }

    function initHelpTooltipLayer() {
        prepareSettingsTooltipTriggers(document);
        if (document.body.dataset.helpTooltipBound === "true") return;
        document.body.dataset.helpTooltipBound = "true";
        document.addEventListener("mouseover", (event) => {
            const trigger = event.target.closest(HELP_TOOLTIP_CONFIGS.map((config) => config.triggerSelector).join(", "));
            if (!trigger) return;
            if (helpTooltipOwner === trigger) return;
            showHelpTooltip(trigger);
        });
        document.addEventListener("mouseout", (event) => {
            const scope = getHelpTooltipScope(event.target);
            if (!scope) return;
            if (scope.contains(event.relatedTarget)) return;
            hideHelpTooltip();
        });
        document.addEventListener("focusin", (event) => {
            const trigger = event.target.closest(HELP_TOOLTIP_CONFIGS.map((config) => config.triggerSelector).join(", "));
            if (!trigger) return;
            showHelpTooltip(trigger);
        });
        document.addEventListener("focusout", (event) => {
            const scope = getHelpTooltipScope(event.target);
            if (!scope) return;
            if (scope.contains(event.relatedTarget)) return;
            hideHelpTooltip();
        });
        window.addEventListener("scroll", () => {
            if (helpTooltipOwner) {
                positionHelpTooltip(helpTooltipOwner);
            }
        }, true);
        window.addEventListener("resize", () => {
            if (helpTooltipOwner) {
                positionHelpTooltip(helpTooltipOwner);
            }
        });
    }

    function ensureBillingTooltipLayer() {
        return ensureHelpTooltipLayer();
    }

    function hideBillingTooltip() {
        hideHelpTooltip();
    }

    function positionBillingTooltip(trigger) {
        positionHelpTooltip(trigger);
    }

    function showBillingTooltip(trigger) {
        showHelpTooltip(trigger);
    }

    function initBillingTooltipLayer() {
        initHelpTooltipLayer();
    }

    function ensureProviderStatusTooltipLayer() {
        return ensureHelpTooltipLayer();
    }

    function hideProviderStatusTooltip() {
        hideHelpTooltip();
    }

    function positionProviderStatusTooltip(trigger) {
        positionHelpTooltip(trigger);
    }

    function showProviderStatusTooltip(trigger) {
        showHelpTooltip(trigger);
    }

    function initProviderStatusTooltipLayer() {
        initHelpTooltipLayer();
    }

    function ensureSettingsTooltipLayer() {
        return ensureHelpTooltipLayer();
    }

    function hideSettingsTooltip() {
        hideHelpTooltip();
    }

    function positionSettingsTooltip(trigger) {
        positionHelpTooltip(trigger);
    }

    function showSettingsTooltip(trigger) {
        showHelpTooltip(trigger);
    }

    function initSettingsTooltipLayer() {
        initHelpTooltipLayer();
    }

    function formatPercent(value) {
        if (value == null || Number.isNaN(Number(value))) return "-";
        return `${Number(value).toFixed(2)}%`;
    }

    function formatLatencyMs(value) {
        if (value == null || Number.isNaN(Number(value))) return "-";
        return `${Math.round(Number(value))} ms`;
    }

    function formatBytes(value) {
        if (value == null) return "-";
        const number = Number(value);
        if (!Number.isFinite(number) || number < 0) return "-";
        const units = ["B", "KB", "MB", "GB", "TB"];
        let normalized = number;
        let index = 0;
        while (normalized >= 1024 && index < units.length - 1) {
            normalized /= 1024;
            index += 1;
        }
        const digits = normalized >= 100 || index === 0 ? 0 : normalized >= 10 ? 1 : 2;
        return `${normalized.toFixed(digits)} ${units[index]}`;
    }

    function formatDurationSeconds(value) {
        const seconds = Math.max(0, Math.floor(Number(value) || 0));
        const days = Math.floor(seconds / 86400);
        const hours = Math.floor((seconds % 86400) / 3600);
        const minutes = Math.floor((seconds % 3600) / 60);
        if (days > 0) return `${days}天 ${hours}h`;
        if (hours > 0) return `${hours}h ${minutes}m`;
        return `${minutes}m`;
    }

    function formatScore(value) {
        if (value == null || Number.isNaN(Number(value))) return "-";
        return `${Number(value).toFixed(2)} 分`;
    }

    function renderQualitySummary(entity) {
        return `
            <div>成功率 ${escapeHtml(formatPercent(entity.success_rate))}</div>
            <div class="table-muted">首 Token ${escapeHtml(formatLatencyMs(entity.avg_first_token_latency_ms))}</div>
            <div class="table-muted">稳定性 ${escapeHtml(formatScore(entity.stability_score))} · 样本 ${escapeHtml(String(entity.recent_request_count ?? 0))}</div>
        `;
    }

    function formatHealthOverview(healthyCount, degradedCount, unhealthyCount) {
        return `健康 ${healthyCount} / 异常 ${Number(degradedCount || 0) + Number(unhealthyCount || 0)}`;
    }

    function formatStatusBadgeLabel(value) {
        if (value in HEALTH_STATUS_LABELS) return formatHealthStatusLabel(value);
        if (value in CIRCUIT_STATE_LABELS) return formatCircuitStateLabel(value);
        if (value in API_KEY_STATUS_LABELS) return formatApiKeyStatusLabel(value);
        return String(value ?? "-");
    }

    function normalizeProviderAvailability(value) {
        const normalized = String(value || "unknown");
        return normalized in PROVIDER_AVAILABILITY_LABELS ? normalized : "unknown";
    }

    function formatProviderAvailabilityLabel(value) {
        return PROVIDER_AVAILABILITY_LABELS[normalizeProviderAvailability(value)];
    }

    function providerAvailabilityBadge(value) {
        const normalized = normalizeProviderAvailability(value);
        return `<span class="status-badge status-${normalized}">${escapeHtml(formatProviderAvailabilityLabel(normalized))}</span>`;
    }

    function trustStatusBadge(value, label) {
        const normalized = String(value || "unknown");
        const tone = {
            trusted: "healthy",
            partially_trusted: "degraded",
            untrusted: "unhealthy",
            abnormal: "unhealthy",
            unknown: "unknown",
        }[normalized] || "unknown";
        const text = label || (normalized in PROVIDER_TRUST_STATUS_LABELS
            ? formatProviderTrustStatusLabel(normalized)
            : formatModelTrustStatusLabel(normalized));
        return `<span class="status-badge status-${tone}">${escapeHtml(text)}</span>`;
    }

    function renderTrustStatusWithHint(status, label, reason, title = "可信度说明") {
        const normalizedReason = String(reason || "").trim();
        return `
            <span class="provider-status-cell">
                ${trustStatusBadge(status, label)}
                ${status !== "trusted" && normalizedReason ? `
                    <span class="provider-status-help">
                        <button class="provider-status-help-btn" type="button" aria-label="${escapeHtml(title)}" data-provider-status-tooltip-trigger="true">
                            <i class="bi bi-question-circle" aria-hidden="true"></i>
                        </button>
                        <div class="provider-status-tooltip-content hidden">
                            <div class="provider-status-tooltip-title">${escapeHtml(title)}</div>
                            <div class="provider-status-tooltip-copy">${escapeHtml(normalizedReason)}</div>
                        </div>
                    </span>
                ` : ""}
            </span>
        `;
    }

    function summarizeEnabledModelHealth(modelConfigs = []) {
        const enabledModels = modelConfigs.filter((item) => item.enabled);
        return enabledModels.reduce((summary, item) => {
            const status = String(item.health_status || "unknown");
            summary.total += 1;
            if (status === "healthy") summary.healthy += 1;
            else if (status === "degraded" || status === "unhealthy") summary.unhealthy += 1;
            else summary.unknown += 1;
            return summary;
        }, {
            total: 0,
            healthy: 0,
            unhealthy: 0,
            unknown: 0,
        });
    }

    function renderProviderAvailability(provider = {}) {
        const modelConfigs = Array.isArray(provider.model_configs) ? provider.model_configs : [];
        const summary = summarizeEnabledModelHealth(modelConfigs);
        const detail = summary.total
            ? `启用 ${formatNumber(summary.total)}：健康 ${formatNumber(summary.healthy)} / 异常 ${formatNumber(summary.unhealthy)}${summary.unknown ? ` / 未检测 ${formatNumber(summary.unknown)}` : ""}`
            : (modelConfigs.length ? "无启用模型" : "未挂载模型");
        return `
            <div class="provider-availability-summary">
                <div class="provider-availability-main">${providerAvailabilityBadge(provider.health_status)}</div>
                <div class="provider-availability-meta">${escapeHtml(detail)}</div>
            </div>
        `;
    }

    function renderProviderModelHealth(modelConfigs = [], providerId) {
        if (!modelConfigs.length) return '<span class="table-muted">未挂载模型</span>';
        const visibleModels = modelConfigs.slice(0, 1);
        const enabledCount = modelConfigs.filter((item) => item.enabled).length;
        const healthyCount = modelConfigs.filter((item) => item.health_status === "healthy").length;
        const hiddenCount = Math.max(modelConfigs.length - visibleModels.length, 0);
        return `
            <div class="provider-model-summary">
                <div class="provider-model-summary-head">
                    <strong>${formatNumber(modelConfigs.length)} 个模型</strong>
                    <span>${formatNumber(enabledCount)} 启用 · ${formatNumber(healthyCount)} 模型健康 · ${summarizeModelCapabilities(modelConfigs)}</span>
                </div>
                <div class="provider-model-preview-list">
                    ${visibleModels.map((item) => `
                        <span class="provider-model-preview-chip">
                            <strong>${escapeHtml(item.model_name)}</strong>
                            <span>${escapeHtml(formatMultiplier(item.price_multiplier ?? 1))}</span>
                        </span>
                    `).join("")}
                    ${hiddenCount ? `<span class="provider-model-more-chip">+${formatNumber(hiddenCount)}</span>` : ""}
                </div>
                ${hiddenCount ? `<button class="table-action-btn provider-model-detail-btn" data-action="view-models" data-id="${providerId}" type="button">查看全部</button>` : ""}
            </div>
        `;
    }

    function escapeHtml(value) {
        return String(value)
            .replaceAll("&", "&amp;")
            .replaceAll("<", "&lt;")
            .replaceAll(">", "&gt;")
            .replaceAll('"', "&quot;")
            .replaceAll("'", "&#39;");
    }

    function formatDate(value) {
        if (!value) return "-";
        let normalized = value;
        if (typeof value === "string") {
            normalized = value.includes("T") ? value : value.replace(" ", "T");
            if (!/[zZ]|[+\-]\d{2}:\d{2}$/.test(normalized)) {
                normalized = `${normalized}Z`;
            }
        }
        const date = new Date(normalized);
        if (Number.isNaN(date.getTime())) return String(value);
        return date.toLocaleString("zh-CN", { hour12: false });
    }

    function formatNumber(value) {
        const normalized = Number(value ?? 0);
        if (!Number.isFinite(normalized)) return "-";
        return normalized.toLocaleString("zh-CN");
    }

